SELECT id, enterprise_id, member_id, product_code, metric_code, bucket_date,
       daily_limit, reserved_count, used_count, version
FROM fbs_usage_budget
WHERE enterprise_id = #{tenantId}
  AND member_id = #{memberId}
  AND product_code = #{productCode}
  AND metric_code = #{metricCode}
  AND bucket_date = #{bucketDate,jdbcType=DATE}
LIMIT 1

mapper.update:
UPDATE fbs_usage_budget
SET daily_limit = #{dailyLimit},
    reserved_count = reserved_count + 1,
    version = version + 1,
    updated_at = NOW()
WHERE enterprise_id = #{tenantId}
  AND member_id = #{memberId}
  AND product_code = #{productCode}
  AND metric_code = #{metricCode}
  AND bucket_date = #{bucketDate,jdbcType=DATE}
  AND used_count + reserved_count < #{dailyLimit}

