       product_code, metric_code, bucket_date, units, status, effective_plan_code,
       agenda_count, seat_count, remaining_count, created_at, updated_at, completed_at
FROM fbs_usage_operation
WHERE enterprise_id = #{tenantId}
  AND product_code = #{productCode}
  AND metric_code = #{metricCode}
ORDER BY created_at DESC, id DESC
LIMIT 501

